-- Check the wtyclaimcnt values more carefully - what's the threshold?
-- "Warranty Claim Threshold" likely means panels with active warranty (wtystatus = 'Active')
SELECT wtystatus, COUNT(*) as cnt FROM maintenance GROUP BY wtystatus;

-- Check if there are panels without maintenance records
SELECT COUNT(*) as total_panels FROM panel;
SELECT COUNT(DISTINCT compref) as panels_with_maint FROM maintenance WHERE compref IS NOT NULL;
